<script setup lang="ts">
const db=useSupabaseClient()
const email=ref(''),password=ref(''),given=ref(''),family=ref(''),school=ref(''),busy=ref(false),error=ref(''),message=ref('')
async function lookup(){school.value='';if(!email.value.includes('@'))return;const {data}=await db.rpc('school_for_signup_email',{p_email:email.value.trim()});school.value=data?.[0]?.school_name||''}
async function register(){error.value='';message.value='';await lookup();if(!school.value){error.value='This email domain has not been approved by a school administrator.';return}busy.value=true;const {data,error:e}=await db.auth.signUp({email:email.value.trim(),password:password.value,options:{data:{full_name:`${given.value.trim()} ${family.value.trim()}`},emailRedirectTo:`${window.location.origin}/student/onboarding`}});busy.value=false;if(e){error.value=e.message;return}message.value='Check your school email for the confirmation link. After confirming, sign in to submit your school access request.';if(data.session)await navigateTo('/student/onboarding')}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/login">← Sign in</NuxtLink><form class="auth" @submit.prevent="register"><h1>Student Sign Up</h1><p>Use your approved school email address. Your school must verify your account before you can enter events.</p><label class="field"><span>First name</span><input v-model="given" required maxlength="100" autocomplete="given-name"></label><label class="field"><span>Last name</span><input v-model="family" required maxlength="100" autocomplete="family-name"></label><label class="field"><span>School email</span><input v-model="email" type="email" required autocomplete="email" @blur="lookup"></label><p v-if="school" class="success">School: {{school}}</p><label class="field"><span>Password (minimum 8 characters)</span><input v-model="password" type="password" required minlength="8" autocomplete="new-password"></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><button class="btn" :disabled="busy">{{busy?'Creating account…':'Create Student Account'}}</button></form></div></div></template>
